const e={privacy:{discord:{title:"Join the community",subtitle:"Official Server"},badge:"Full Transparency",title_p1:"Privacy",title_p2:"Policy",description:"Your peace of mind is our priority. Here we explain how we take care of your data with the same passion with which we create every pixel of our games.",last_update:"24/12/2025",sections:{intro:{title:"Introduction",content:"At GameBob, we take our users' privacy very seriously. This policy describes how data is handled in all our apps and games. We believe in ethical development where fun doesn't depend on your personal information."},collection:{title:"Data Collection",content:"Our games are designed to be enjoyed without collecting personally identifiable information. We do not request names, emails, or sensitive information. Your progress is yours, and we want it to stay that way."},security:{title:"Security Philosophy",content:"We implement a 'Zero Data' policy. We do not store information on external servers that is not strictly necessary for the local technical operation of the application, minimizing any risk of exposure."},third_party:{title:"Third-Party Services",admob_title:"Google AdMob:",admob_content:"Used to show ads that fund our free development. Google may use anonymous advertising identifiers to personalize your advertising experience.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Error monitoring tool that helps us identify, prioritize, and fix app stability issues. It collects anonymous data about crashes and the app state at the time of the error."},children:{title:"Child Protection",content:"We strictly comply with international child protection regulations (COPPA/GDPR). Our games are safe environments where personal information from children under 13 is not collected under any circumstances."},contact:{title:"Changes and Contact",content:"Our policy may evolve along with our technology. If you have any questions about how we protect your gaming experience, we are just a message away through our official channels."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Legal Framework",title_p1:"Terms and",title_p2:"Conditions",description:"The rules of the game. Transparency and clarity for a better experience.",last_update:"02/01/2026",intro_p1:"Welcome to the services provided by Game Bob (jjlmoya).",intro_p2:'By downloading, installing, or using any of our mobile applications ("the Application") or accessing our website, you agree to be bound by the following Terms and Conditions. If you do not agree to these terms, please do not use the Application.',sections:{license:{title:"License of Use",content:"The user is granted a personal, non-exclusive, non-transferable, and revocable license to use the Application on compatible mobile devices, exclusively for personal and non-commercial purposes."},acceptable:{title:"Acceptable Use",content:"You agree to use the Application only for lawful purposes and in accordance with these Terms. It is prohibited to:",items:["Reverse engineer, decompile, or attempt to extract the source code of the Application.","Use the Application in a way that could damage, disable, or overload our servers or networks.","Circumvent any security measure or technical restriction of the Application."]},intellectual:{title:"Intellectual Property",content:"All intellectual property rights over the design, source code, graphics, logos, and content of our applications are the exclusive property of jjlmoya or are used under license. No ownership rights are transferred to the user."},privacy:{title:"Privacy and Data Protection",content:"Your privacy is important to us. The use of the Application is also governed by our Privacy Policy, which describes how we collect, use, and share information (e.g., advertising identifiers or anonymous usage data).",link_text:"Read full Privacy Policy"},third_party:{title:"Third-Party Services",content:"The application may integrate third-party services (such as Google AdMob for advertising or Firebase for analytics). Use of these services is subject to the terms and policies of those providers. Game Bob does not control or assume responsibility for the content or practices of these external services."},liability:{title:"Limitation of Liability",content:'The Application is provided "as is". Game Bob does not guarantee that the Application will be error-free or operate without interruptions. To the maximum extent permitted by law, we will not be responsible for any direct, indirect, or consequential damages arising from the use or inability to use the Application.'},modifications:{title:"Modifications",content:"We reserve the right to update or modify these Terms at any time. Modifications will take effect upon publication. Continued use of the Application will constitute your acceptance of such modifications."},jurisdiction:{title:"Legislation and Jurisdiction",content:"These Terms shall be governed and interpreted in accordance with the laws of Spain. Any dispute arising in connection with these Terms shall be subject to the exclusive jurisdiction of the Spanish courts."},contact:{title:"Contact",content:"If you have any questions or concerns about these Terms and Conditions, you can contact us at:"}},footer_copy:"GameBob Studio © 2026"}},i={privacy:{discord:{title:"Únete a la comunidad",subtitle:"Servidor Oficial"},badge:"Transparencia Total",title_p1:"Política de",title_p2:"Privacidad",description:"Tu tranquilidad es nuestra prioridad. Aquí explicamos cómo cuidamos tus datos con la misma pasión con la que creamos cada píxel de nuestros juegos.",last_update:"24/12/2025",sections:{intro:{title:"Introducción",content:"En GameBob, nos tomamos muy en serio la privacidad de nuestros usuarios. Esta política describe cómo se manejan los datos en todas nuestras aplicaciones y juegos. Creemos en un desarrollo ético donde la diversión no dependa de tu información personal."},collection:{title:"Recopilación de Datos",content:"Nuestros juegos están diseñados para ser disfrutados sin recopilar datos personales identificables. No solicitamos nombres, correos electrónicos ni información sensible. Tu progreso es tuyo, y así queremos que siga siendo."},security:{title:"Filosofía de Seguridad",content:"Implementamos una política de 'Zero Data'. No almacenamos información en servidores externos que no sea estrictamente necesaria para el funcionamiento técnico local de la aplicación, minimizando cualquier riesgo de exposición."},third_party:{title:"Servicios de Terceros",admob_title:"Google AdMob:",admob_content:"Utilizado para mostrar anuncios que financian nuestro desarrollo gratuito. Google puede usar identificadores de publicidad anónimos para personalizar tu experiencia publicitaria.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Herramienta de monitoreo de errores que nos ayuda a identificar, priorizar y solucionar problemas de estabilidad en la aplicación. Recopila datos anónimos sobre fallos y el estado de la aplicación en el momento del error."},children:{title:"Protección Infantil",content:"Cumplimos estrictamente con las normativas internacionales de protección infantil (COPPA/GDPR). Nuestros juegos son entornos seguros donde no se recopila información personal de menores de 13 años bajo ningún concepto."},contact:{title:"Cambios y Contacto",content:"Nuestra política puede evolucionar junto con nuestra tecnología. Si tienes alguna duda sobre cómo protegemos tu experiencia de juego, estamos a un mensaje de distancia a través de nuestros canales oficiales."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Marco Legal",title_p1:"Términos y",title_p2:"Condiciones",description:"Las reglas del juego. Transparencia y claridad para una mejor experiencia.",last_update:"02/01/2026",intro_p1:"Bienvenido a los servicios proporcionados por Game Bob (jjlmoya).",intro_p2:'Al descargar, instalar o utilizar cualquiera de nuestras aplicaciones móviles ("la Aplicación") o acceder a nuestro sitio web, usted acepta estar sujeto a los siguientes Términos y Condiciones. Si no está de acuerdo con estos términos, le rogamos que no utilice la Aplicación.',sections:{license:{title:"Licencia de Uso",content:"Se concede al usuario una licencia personal, no exclusiva, intransferible y revocable para utilizar la Aplicación en dispositivos móviles compatibles, exclusivamente para fines personales y no comerciales."},acceptable:{title:"Uso Aceptable",content:"Usted se compromete a utilizar la Aplicación únicamente para fines legales y de acuerdo con estos Términos. Queda prohibido:",items:["Realizar ingeniería inversa, descompilar o intentar extraer el código fuente de la Aplicación.","Utilizar la Aplicación de manera que pueda dañar, deshabilitar o sobrecargar nuestros servidores o redes.","Eludir cualquier medida de seguridad o restricción técnica de la Aplicación."]},intellectual:{title:"Propiedad Intelectual",content:"Todos los derechos de propiedad intelectual sobre el diseño, código fuente, gráficos, logotipos y contenido de nuestras aplicaciones son propiedad exclusiva de jjlmoya o se utilizan bajo licencia. No se transfiere ningún derecho de propiedad al usuario."},privacy:{title:"Privacidad y Protección de Datos",content:"Su privacidad es importante para nosotros. El uso de la Aplicación también se rige por nuestra Política de Privacidad, que describe cómo recopilamos, utilizamos y compartimos la información (por ejemplo, identificadores de publicidad o datos anónimos de uso).",link_text:"Leer Política de Privacidad completa"},third_party:{title:"Servicios de Terceros",content:"La aplicación puede integrar servicios de terceros (como Google AdMob para publicidad o Firebase para análisis). El uso de estos servicios está sujeto a los términos y políticas de dichos proveedores. Game Bob no controla ni asume responsabilidad por el contenido o las prácticas de estos servicios externos."},liability:{title:"Limitación de Responsabilidad",content:'La Aplicación se proporciona "tal cual". Game Bob no garantiza que la Aplicación esté libre de errores o funcione sin interrupciones. En la medida máxima permitida por la ley, no seremos responsables de ningún daño directo, indirecto o consecuente derivado del uso o la imposibilidad de uso de la Aplicación, incluidos los resultados de los cálculos teóricos o estimaciones de juego.'},modifications:{title:"Modificaciones",content:"Nos reservamos el derecho de actualizar o modificar estos Términos en cualquier momento. Las modificaciones entrarán en vigor en el momento de su publicación. El uso continuado de la Aplicación constituirá su aceptación de dichas modificaciones."},jurisdiction:{title:"Legislación y Jurisdicción",content:"Estos Términos se regirán e interpretarán de acuerdo con las leyes de España. Cualquier disputa que surja en relación con estos Términos estará sujeta a la jurisdicción exclusiva de los tribunales españoles."},contact:{title:"Contacto",content:"Si tiene alguna pregunta o duda sobre estos Términos y Condiciones, puede ponerse en contacto con nosotros en:"}},footer_copy:"GameBob Studio © 2026"}},t={privacy:{discord:{title:"Tritt der Community bei",subtitle:"Offizieller Server"},badge:"Volle Transparenz",title_p1:"Datenschutz",title_p2:"bestimmungen",description:"Ihre Sicherheit ist unsere Priorität. Hier erklären wir, wie wir mit Ihren Daten umgehen, mit derselben Leidenschaft, mit der wir jedes Pixel unserer Spiele erstellen.",last_update:"24/12/2025",sections:{intro:{title:"Einführung",content:"Bei GameBob nehmen wir den Schutz Ihrer persönlichen Daten sehr ernst. Diese Richtlinie beschreibt den Umgang mit Daten in all unseren Apps und Spielen. Wir glauben an ethische Entwicklung, bei der der Spaß nicht von Ihren persönlichen Informationen abhängt."},collection:{title:"Datenerhebung",content:"Unsere Spiele sind so konzipiert, dass sie ohne Erhebung personenbezogener Daten genossen werden können. Wir fragen nicht nach Namen, E-Mails oder sensiblen Informationen. Ihr Fortschritt gehört Ihnen, und das soll auch so bleiben."},security:{title:"Sicherheitsphilosophie",content:"Wir verfolgen eine 'Zero Data'-Politik. Wir speichern keine Informationen auf externen Servern, die nicht unbedingt für den lokalen technischen Betrieb der Anwendung erforderlich sind, um jedes Risiko einer Offenlegung zu minimieren."},third_party:{title:"Dienste von Drittanbietern",admob_title:"Google AdMob:",admob_content:"Wird verwendet, um Anzeigen anzuzeigen, die unsere kostenlose Entwicklung finanzieren. Google kann anonyme Werbe-Identifikatoren verwenden, um Ihr Werbeerlebnis zu personalisieren.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Tool zur Fehlerüberwachung, das uns hilft, Stabilitätsprobleme in der App zu identifizieren, zu priorisieren und zu beheben. Es sammelt anonyme Daten über Abstürze und den Zustand der App zum Zeitpunkt des Fehlers."},children:{title:"Kinderschutz",content:"Wir halten uns strikt an internationale Kinderschutzbestimmungen (COPPA/DSGVO). Unsere Spiele sind sichere Umgebungen, in denen unter keinen Umständen personenbezogene Daten von Kindern unter 13 Jahren erhoben werden."},contact:{title:"Änderungen und Kontakt",content:"Unsere Richtlinien können sich zusammen mit unserer Technologie weiterentwickeln. Wenn Sie Fragen dazu haben, wie wir Ihr Spielerlebnis schützen, sind wir nur eine Nachricht über unsere offiziellen Kanäle entfernt."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Rechtlicher Rahmen",title_p1:"Allgemeine Geschäfts",title_p2:"bedingungen",description:"Die Spielregeln. Transparenz und Klarheit für ein besseres Erlebnis.",last_update:"02/01/2026",intro_p1:"Willkommen bei den Diensten von Game Bob (jjlmoya).",intro_p2:"Durch das Herunterladen, Installieren oder Verwenden einer unserer mobilen Anwendungen („die Anwendung“) oder den Zugriff auf unsere Website erklären Sie sich mit den folgenden Allgemeinen Geschäftsbedingungen einverstanden. Wenn Sie diesen Bedingungen nicht zustimmen, nutzen Sie die Anwendung bitte nicht.",sections:{license:{title:"Nutzungslizenz",content:"Dem Nutzer wird eine persönliche, nicht exklusive, nicht übertragbare und widerrufbare Lizenz zur Nutzung der Anwendung auf kompatiblen mobilen Geräten ausschließlich für persönliche und nicht kommerzielle Zwecke gewährt."},acceptable:{title:"Zulässige Nutzung",content:"Sie erklären sich damit einverstanden, die Anwendung nur für rechtmäßige Zwecke und in Übereinstimmung mit diesen Bedingungen zu nutzen. Es ist untersagt:",items:["Die Anwendung zurückzuentwickeln, zu dekompilieren oder zu versuchen, den Quellcode zu extrahieren.","Die Anwendung in einer Weise zu nutzen, die unsere Server oder Netzwerke beschädigen, deaktivieren oder überlasten könnte.","Sicherheitsmaßnahmen oder technische Einschränkungen der Anwendung zu umgehen."]},intellectual:{title:"Geistiges Eigentum",content:"Alle geistigen Eigentumsrechte am Design, Quellcode, Grafiken, Logos und Inhalten unserer Anwendungen sind das ausschließliche Eigentum von jjlmoya oder werden unter Lizenz verwendet. Es werden keine Eigentumsrechte an den Nutzer übertragen."},privacy:{title:"Datenschutz",content:"Ihre Privatsphäre ist uns wichtig. Die Nutzung der Anwendung unterliegt auch unserer Datenschutzrichtlinie, die beschreibt, wie wir Informationen sammeln, verwenden und weitergeben (z. B. Werbe-Identifikatoren oder anonyme Nutzungsdaten).",link_text:"Vollständige Datenschutzrichtlinie lesen"},third_party:{title:"Dienste von Drittanbietern",content:"Die Anwendung kann Dienste von Drittanbietern integrieren (wie Google AdMob für Werbung oder Firebase für Analysen). Die Nutzung dieser Dienste unterliegt den Bedingungen und Richtlinien dieser Anbieter. Game Bob kontrolliert oder übernimmt keine Verantwortung für den Inhalt oder die Praktiken dieser externen Dienste."},liability:{title:"Haftungsbeschränkung",content:"Die Anwendung wird „wie besehen“ bereitgestellt. Game Bob garantiert nicht, dass die Anwendung fehlerfrei ist oder ohne Unterbrechungen funktioniert. Im gesetzlich zulässigen Rahmen haften wir nicht für direkte, indirekte oder Folgeschäden, die aus der Nutzung oder der Unmöglichkeit der Nutzung der Anwendung entstehen."},modifications:{title:"Änderungen",content:"Wir behalten uns das Recht vor, diese Bedingungen jederzeit zu aktualisieren oder zu ändern. Änderungen treten mit der Veröffentlichung in Kraft. Die fortgesetzte Nutzung der Anwendung gilt als Ihre Zustimmung zu solchen Änderungen."},jurisdiction:{title:"Recht und Gerichtsbarkeit",content:"Diese Bedingungen unterliegen dem spanischen Recht und werden nach diesem ausgelegt. Alle Streitigkeiten im Zusammenhang mit diesen Bedingungen unterliegen der ausschließlichen Zuständigkeit der spanischen Gerichte."},contact:{title:"Kontakt",content:"Wenn Sie Fragen oder Bedenken zu diesen Allgemeinen Geschäftsbedingungen haben, können Sie uns kontaktieren unter:"}},footer_copy:"GameBob Studio © 2026"}},n={privacy:{discord:{title:"Rejoignez la communauté",subtitle:"Serveur Officiel"},badge:"Transparence Totale",title_p1:"Politique de",title_p2:"Confidentialité",description:"Votre tranquillité d'esprit est notre priorité. Nous expliquons ici comment nous prenons soin de vos données avec la même passion que celle avec laquelle nous créons chaque pixel de nos jeux.",last_update:"24/12/2025",sections:{intro:{title:"Introduction",content:"Chez GameBob, nous prenons la confidentialité de nos utilisateurs très au sérieux. Cette politique décrit comment les données sont gérées dans toutes nos applications et jeux. Nous croyons en un développement éthique où le plaisir ne dépend pas de vos informations personnelles."},collection:{title:"Collecte de Données",content:"Nos jeux sont conçus pour être appréciés sans collecte d'informations personnellement identifiables. Nous ne demandons ni noms, ni e-mails, ni informations sensibles. Votre progression vous appartient, et nous voulons qu'il en soit ainsi."},security:{title:"Philosophie de Sécurité",content:"Nous appliquons une politique 'Zéro Donnée'. Nous ne stockons pas d'informations sur des serveurs externes qui ne soient pas strictement nécessaires au fonctionnement technique local de l'application, minimisant ainsi tout risque d'exposition."},third_party:{title:"Services Tiers",admob_title:"Google AdMob :",admob_content:"Utilisé pour afficher des publicités qui financent notre développement gratuit. Google peut utiliser des identifiants publicitaires anonymes pour personnaliser votre expérience publicitaire.",crashlytics_title:"Firebase Crashlytics :",crashlytics_content:"Outil de surveillance des erreurs qui nous aide à identifier, prioriser et corriger les problèmes de stabilité de l'application. Il collecte des données anonymes sur les plantages et l'état de l'application au moment de l'erreur."},children:{title:"Protection de l'Enfance",content:"Nous respectons strictement les réglementations internationales de protection de l'enfance (COPPA/RGPD). Nos jeux sont des environnements sûrs où aucune information personnelle d'enfants de moins de 13 ans n'est collectée en aucun cas."},contact:{title:"Changements et Contact",content:"Notre politique peut évoluer avec notre technologie. Si vous avez des questions sur la manière dont nous protégeons votre expérience de jeu, nous sommes à votre disposition via nos canaux officiels."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Cadre Légal",title_p1:"Conditions Générales",title_p2:"d'Utilisation",description:"Les règles du jeu. Transparence et clarté pour une meilleure expérience.",last_update:"02/01/2026",intro_p1:"Bienvenue dans les services fournis par Game Bob (jjlmoya).",intro_p2:`En téléchargeant, installant ou utilisant l'une de nos applications mobiles ("l'Application") ou en accédant à notre site web, vous acceptez d'être lié par les Conditions Générales suivantes. Si vous n'êtes pas d'accord avec ces conditions, veuillez ne pas utiliser l'Application.`,sections:{license:{title:"Licence d'Utilisation",content:"L'utilisateur bénéficie d'une licence personnelle, non exclusive, non transférable et révocable d'utiliser l'Application sur des appareils mobiles compatibles, exclusivement à des fins personnelles et non commerciales."},acceptable:{title:"Utilisation Acceptable",content:"Vous acceptez n'utiliser l'Application qu'à des fins licites et conformément aux présentes Conditions. Il est interdit de :",items:["Pratiquer l'ingénierie inverse, décompiler ou tenter d'extraire le code source de l'Application.","Utiliser l'Application d'une manière qui pourrait endommager, désactiver ou surcharger nos serveurs ou réseaux.","Contourner toute mesure de sécurité ou restriction technique de l'Application."]},intellectual:{title:"Propriété Intellectuelle",content:"Tous les droits de propriété intellectuelle sur le design, le code source, les graphismes, les logos et le contenu de nos applications sont la propriété exclusive de jjlmoya ou sont utilisés sous licence. Aucun droit de propriété n'est transféré à l'utilisateur."},privacy:{title:"Confidentialité",content:"Votre vie privée est importante pour nous. L'utilisation de l'Application est également régie par notre Politique de Confidentialité, qui décrit comment nous collectons, utilisons et partageons les informations (par ex., identifiants publicitaires ou données d'utilisation anonymes).",link_text:"Lire la politique de confidentialité complète"},third_party:{title:"Services Tiers",content:"L'application peut intégrer des services tiers (comme Google AdMob pour la publicité ou Firebase pour l'analyse). L'utilisation de ces services est soumise aux conditions et politiques de ces fournisseurs. Game Bob ne contrôle ni n'assume aucune responsabilité quant au contenu ou aux pratiques de ces services externes."},liability:{title:"Limitation de Responsabilité",content:`L'Application est fournie "en l'état". Game Bob ne garantit pas que l'Application sera exempte d'erreurs ou fonctionnera sans interruption. Dans toute la mesure permise par la loi, nous ne serons pas responsables des dommages directs, indirects ou consécutifs résultant de l'utilisation ou de l'incapacité d'utiliser l'Application.`},modifications:{title:"Modifications",content:"Nous nous réservons le droit de mettre à jour ou de modifier les présentes Conditions à tout moment. Les modifications prendront effet dès leur publication. L'utilisation continue de l'Application constituera votre acceptation de ces modifications."},jurisdiction:{title:"Législation et Juridiction",content:"Les présentes Conditions sont régies et interprétées conformément aux lois de l'Espagne. Tout litige relatif à ces Conditions sera soumis à la juridiction exclusive des tribunaux espagnols."},contact:{title:"Contact",content:"Si vous avez des questions ou des préoccupations concernant les présentes Conditions Générales, vous pouvez nous contacter à :"}},footer_copy:"GameBob Studio © 2026"}},a={privacy:{discord:{title:"Unisciti alla community",subtitle:"Server Ufficiale"},badge:"Trasparenza Totale",title_p1:"Informativa sulla",title_p2:"Privacy",description:"La tua tranquillità è la nostra priorità. Qui spieghiamo come ci prendiamo cura dei tuoi dati con la stessa passione con cui creiamo ogni pixel dei nostri giochi.",last_update:"24/12/2025",sections:{intro:{title:"Introduzione",content:"In GameBob, prendiamo molto seriamente la privacy dei nostri utenti. Questa informativa descrive come vengono gestiti i dati in tutte le nostre applicazioni e giochi. Crediamo in uno sviluppo etico in cui il divertimento non dipenda dalle tue informazioni personali."},collection:{title:"Raccolta Dati",content:"I nostri giochi sono progettati per essere fruiti senza raccogliere informazioni di identificazione personale. Non richiediamo nomi, e-mail o informazioni sensibili. I tuoi progressi sono tuoi e vogliamo che rimangano tali."},security:{title:"Filosofia di Sicurezza",content:"Applichiamo una politica 'Zero Dati'. Non memorizziamo informazioni su server esterni che non siano strettamente necessarie per il funzionamento tecnico locale dell'applicazione, riducendo al minimo qualsiasi rischio di esposizione."},third_party:{title:"Servizi di Terze Parti",admob_title:"Google AdMob:",admob_content:"Utilizzato per mostrare annunci che finanziano il nostro sviluppo gratuito. Google può utilizzare identificatori pubblicitari anonimi per personalizzare la tua esperienza pubblicitaria.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Strumento di monitoraggio degli errori che ci aiuta a identificare, dare priorità e risolvere i problemi di stabilità dell'applicazione. Raccoglie dati anonimi sui crash e sullo stato dell'applicazione al momento dell'errore."},children:{title:"Protezione dei Minori",content:"Rispettiamo rigorosamente le normative internazionali sulla protezione dei minori (COPPA/GDPR). I nostri giochi sono ambienti sicuri in cui non vengono raccolte informazioni personali di minori di 13 anni in nessun caso."},contact:{title:"Cambiamenti e Contatti",content:"La nostra informativa può evolversi insieme alla nostra tecnologia. Se hai domande su come proteggiamo la tua esperienza di gioco, siamo a tua disposizione tramite i nostri canali ufficiali."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Quadro Legale",title_p1:"Termini e",title_p2:"Condizioni",description:"Le regole del gioco. Trasparenza e chiarezza per un'esperienza migliore.",last_update:"02/01/2026",intro_p1:"Benvenuti ai servizi forniti da Game Bob (jjlmoya).",intro_p2:`Scaricando, installando o utilizzando una qualsiasi delle nostre applicazioni mobili ("l'Applicazione") o accedendo al nostro sito web, l'utente accetta di essere vincolato dai seguenti Termini e Condizioni. Se non si accettano questi termini, si prega di non utilizzare l'Applicazione.`,sections:{license:{title:"Licenza d'Uso",content:"All'utente viene concessa una licenza personale, non esclusiva, non trasferibile e revocabile per utilizzare l'Applicazione su dispositivi mobili compatibili, esclusivamente per scopi personali e non commerciali."},acceptable:{title:"Uso Accettabile",content:"L'utente accetta di utilizzare l'Applicazione solo per scopi leciti e in conformità con i presenti Termini. È vietato:",items:["Effettuare il reverse engineering, decompilare o tentare di estrarre il codice sorgente dell'Applicazione.","Utilizzare l'Applicazione in un modo che possa danneggiare, disabilitare o sovraccaricare i nostri server o reti.","Aggirare qualsiasi misura di sicurezza o restrizione tecnica dell'Applicazione."]},intellectual:{title:"Proprietà Intellettuale",content:"Tutti i diritti di proprietà intellettuale sul design, il codice sorgente, la grafica, i loghi e il contenuto delle nostre applicazioni sono di proprietà esclusiva di jjlmoya o sono utilizzati su licenza. All'utente non viene trasferito alcun diritto di proprietà."},privacy:{title:"Privacy",content:"La tua privacy è importante per noi. L'uso dell'Applicazione è regolato anche dalla nostra Informativa sulla Privacy, che descrive come raccogliamo, utilizziamo e condividiamo le informazioni (ad es. identificatori pubblicitari o dati di utilizzo anonimi).",link_text:"Leggi l'Informativa sulla Privacy completa"},third_party:{title:"Servizi di Terze Parti",content:"L'applicazione può integrare servizi di terze parti (come Google AdMob per la pubblicità o Firebase per le analisi). L'uso di questi servizi è soggetto ai termini e alle politiche di tali fornitori. Game Bob non controlla né si assume alcuna responsabilità per il contenuto o le pratiche di questi servizi esterni."},liability:{title:"Limitazione di Responsabilidade",content:`L'Applicazione viene fornita "così com'è". Game Bob non garantisce che l'Applicazione sia priva di errori o funzioni senza interruzioni. Nella misura massima consentita dalla legge, non saremo responsabili per eventuali danni diretti, indiretti o consequenziali derivanti dall'uso o dall'impossibilità di usare l'Applicazione.`},modifications:{title:"Modifiche",content:"Ci riserviamo il diritto di aggiornare o modificare i presenti Termini in qualsiasi momento. Le modifiche entreranno in vigore al momento della pubblicazione. L'uso continuato dell'Applicazione costituirà l'accettazione di tali modifiche."},jurisdiction:{title:"Legge e Giurisdizione",content:"I presenti Termini sono disciplinati e interpretati in conformità alle leggi della Spagna. Qualsiasi controversia derivante in relazione ai presenti Termini sarà soggetta alla giurisdizione esclusiva dei tribunali spagnoli."},contact:{title:"Contatti",content:"In caso di domande o dubbi sui presenti Termini e Condizioni, è possibile contattarci all'indirizzo:"}},footer_copy:"GameBob Studio © 2026"}},o={privacy:{discord:{title:"Junte-se à comunidade",subtitle:"Servidor Oficial"},badge:"Transparência Total",title_p1:"Política de",title_p2:"Privacidade",description:"A sua tranquilidade é a nossa prioridade. Aqui explicamos como cuidamos dos seus dados com a mesma paixão com que criamos cada píxel dos nossos jogos.",last_update:"24/12/2025",sections:{intro:{title:"Introdução",content:"Na GameBob, levamos muito a sério a privacidade dos nossos utilizadores. Esta política descreve como os dados são tratados em todas as nossas aplicações e jogos. Acreditamos num desenvolvimento ético onde a diversão não depende da sua informação pessoal."},collection:{title:"Recolha de Dados",content:"Os nossos jogos são concebidos para serem desfrutados sem a recolha de informações pessoalmente identificáveis. No pedimos nomes, e-mails ou informações sensíveis. O seu progresso é seu e queremos que continue assim."},security:{title:"Filosofia de Segurança",content:"Implementamos uma política de 'Zero Dados'. Não armazenamos informações em servidores externos que não sejam estritamente necessárias para o funcionamento técnico local da aplicação, minimizando qualquer risco de exposição."},third_party:{title:"Serviços de Terceiros",admob_title:"Google AdMob:",admob_content:"Utilizado para apresentar anúncios que financiam o nosso desenvolvimento gratuito. O Google pode utilizar identificadores de publicidade anónimos para personalizar a sua experiência publicitária.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Ferramenta de monitorização de erros que nos ajuda a identificar, priorizar e fixar problemas de estabilidade na aplicação. Recolhe dados anónimos sobre falhas e o estado da aplicação no momento do erro."},children:{title:"Proteção Infantil",content:"Cumprimos rigorosamente as normas internacionais de proteção infantil (COPPA/RGPD). Os nossos jogos son ambientes seguros onde não é recolhida informação pessoal de menores de 13 anos em circunstância alguma."},contact:{title:"Alterações e Contacto",content:"A nossa política pode evoluir juntamente com a nossa tecnologia. Se tiver alguma dúvida sobre como protegemos a sua experiência de jogo, estamos à distância de uma mensagem através dos nossos canais oficiais."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Quadro Legal",title_p1:"Termos e",title_p2:"Condições",description:"As regras do jogo. Transparência e clareza para uma melhor experiência.",last_update:"02/01/2026",intro_p1:"Bem-vindo aos serviços fornecidos pela Game Bob (jjlmoya).",intro_p2:'Ao descarregar, instalar ou utilizar qualquer uma das nossas aplicações móveis ("a Aplicação") ou ao aceder ao nosso sítio web, o utilizador aceita ficar vinculado pelos seguintes Termos e Condições. Se não concordar com estes termos, por favor não utilize a Aplicação.',sections:{license:{title:"Licença de Uso",content:"É concedida ao utilizador uma licença pessoal, não exclusiva, intransferível e revogável para utilizar a Aplicação em dispositivos móveis compatíveis, exclusivamente para fins pessoais e não comerciais."},acceptable:{title:"Uso Aceitável",content:"O utilizador compromete-se a utilizar a Aplicação apenas para fins legais e de acordo com estes Termos. É proibido:",items:["Efectuar engenharia inversa, descompilar ou tentar extrair o código fonte da Aplicação.","Utilizar la Aplicación de forma que possa danificar, desativar ou sobrecarregar os nossos servidores ou redes.","Contornar qualquer medida de segurança ou restrição técnica da Aplicação."]},intellectual:{title:"Propriedade Intelectual",content:"Todos os direitos de propriedade intelectual sobre o design, código fonte, gráficos, logótipos e conteúdo das nossas aplicações são propriedade exclusiva de jjlmoya ou são utilizados sob licença. Não é transferido qualquer direito de propriedade para o utilizador."},privacy:{discord:{title:"Junte-se à comunidade",subtitle:"Servidor Oficial"},title:"Privacidade e Proteção de Dados",content:"Sua privacidade é importante para nós. O uso da Aplicação também é regido pela nossa Política de Privacidade, que descreve como recolhemos, utilizamos e partilhamos a informação (por exemplo, identificadores de publicidade ou dados anónimos de utilização).",link_text:"Ler Política de Privacidade completa"},third_party:{title:"Serviços de Terceiros",content:"A aplicação pode integrar serviços de terceiros (como o Google AdMob para publicidade ou Firebase para análises). O uso destes serviços está sujeito aos termos e políticas desses fornecedores. A Game Bob não controla nem assume responsabilidade pelo conteúdo ou pelas práticas destes serviços externos."},liability:{title:"Limitação de Responsabilidade",content:'A Aplicação é fornecida "tal como está". A Game Bob não garante que a Aplicação esteja livre de erros ou que funcione sem interrupciones. Na medida máxima permitida pela lei, não seremos responsáveis por quaisquer danos directos, indirectos ou consequentes resultantes da utilização ou da impossibilidade de utilização da Aplicação.'},modifications:{title:"Modificações",content:"Reservamo-nos o direito de atualizar ou modificar estes Termos a qualquer momento. As modificações entrarão em vigor no momento da sua publicação. O uso continuado da Aplicação constituirá a sua aceitação de tais modificações."},jurisdiction:{title:"Legislação e Jurisdição",content:"Estes Termos serão regidos e interpretados de acordo com as leis de Espanha. Qualquer litígio que surja em relação a estes Termos estará sujeito à jurisdição exclusiva dos tribunais espanhóis."},contact:{title:"Contacto",content:"Se tiver alguma dúvida ou preocupação sobre estes Termos e Condições, contacte-nos em:"}},footer_copy:"GameBob Studio © 2026"}},r={privacy:{discord:{title:"コミュニティに参加する",subtitle:"公式サーバー"},badge:"高い透明性",title_p1:"プライバシー",title_p2:"ポリシー",description:"お客様の安心が私たちの優先事項です。私たちがゲームの細部に情熱を注ぐのと同じように、お客様のデータをどのように大切に扱っているかをご説明します。",last_update:"24/12/2025",sections:{intro:{title:"はじめに",content:"GameBobでは、ユーザーのプライバシーを最優先に考えています。このポリシーでは、当社のすべてのアプリケーションおよびゲームにおけるデータの取り扱いについて説明します。楽しみが個人情報に依存しない、倫理的な開発を信じています。"},collection:{title:"データの収集",content:"当社のゲームは、個人を特定できる情報を収集することなく楽しめるように設計されています。氏名、メールアドレス、機密情報を求めることはありません。お客様の進捗はお客様自身のものであり、それを尊重します。"},security:{title:"セキュリティ理念",content:"「ゼロデータ」ポリシーを実施しています。アプリケーションの技術的な運営に厳密に必要でない情報を外部サーバーに保存することはありません。これにより、露出のリスクを最小限に抑えています。"},third_party:{title:"サードパーティサービス",admob_title:"Google AdMob:",admob_content:"無料開発の資金源となる広告の表示に使用されます。Googleは、広告体験をパーソナライズするために、匿名の広告識別子を使用する場合があります。",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"アプリの安定性の問題を特定・修正するためのエラー監視ツールです。クラッシュ時のアプリの状態に関する匿名データを収集します。"},children:{title:"児童保護",content:"国際的な児童保護規制（COPPA/GDPR）を厳格に遵守しています。当社のゲームは、13歳未満の児童からいかなる状況下でも個人情報を収集しない、安全な環境です。"},contact:{title:"変更と連絡先",content:"当社のポリシーは技術の進化に合わせて変更される場合があります。ゲーム体験の保護についてご質問がある場合は、公式チャンネルからお気軽にお問い合わせください。"}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"法的枠組み",title_p1:"利用",title_p2:"規約",description:"ゲームのルール. より良い体験のための透明性と明確さ。",last_update:"02/01/2026",intro_p1:"Game Bob（jjlmoya）が提供するサービスへようこそ。",intro_p2:"当社のモバイルアプリケーション（以下「本アプリ」）をダウンロード、インストール、または使用することにより、、あるいは当社のウェブサイトにアクセスすることにより、お客様は以下の利用規約に同意したものとみなされます。これらの規約に同意いただけない場合は、本アプリを使用しないでください。",sections:{license:{title:"使用許諾",content:"ユーザーには、互換性のあるモバイルデバイスで本アプリを使用するための、個人的、非独占的、譲渡不能、かつ取り消し可能なライセンスが、個人的および非商業的な目的に限定して付与されます。"},acceptable:{title:"禁止事項",content:"お客様は、合法的な目的かつ本規約に従って本アプリを使用することに同意するものとします。以下は禁止されています。",items:["本アプリのソースコードのリバースエンジニアリング、逆コンパイル、または抽出の試み。","当社のサーバーやネットワークを損傷、無効化、または過負荷にする可能性のある方法で本アプリを使用すること。","本アプリのセキュリティ手段や技術的制限を回避すること。"]},intellectual:{title:"知的財産権",content:"当社のアプリのデザイン、ソースコード、グラフィックス、ロゴ、およびコンテンツに関するすべての知的財産権は、jjlmoyaの独占的財産であるか、ライセンスに基づいて使用されています。ユーザーにいかなる所有権も譲渡されません。"},privacy:{discord:{title:"コミュニティに参加する",subtitle:"公式サーバー"},title:"プライバシーとデータ保護",content:"お客様のプライバシーは重要です。本アプリの使用は、情報の収集、使用、共有方法を説明する当社のプライバシーポリシーによっても規定されます。",link_text:"プライバシーポリシー全文を読む"},third_party:{title:"サードパーティサービス",content:"本アプリは、サードパーティのサービス（広告用のGoogle AdMobや分析用のFirebaseなど）を統合する場合があります。これらのサービスの使用には、当該プロバイダーの規約およびポリシーが適用されます。"},liability:{title:"免責事項",content:"本アプリは「現状有姿」で提供されます。Game Bobは、本アプリにエラーがないことや中断なしに動作することを保証しません。法律で認められる最大限の範囲において、本アプリの使用または使用不能から生じる損害について、責任を負いません。"},modifications:{title:"規約の変更",content:"当社は、いつでも本規約を更新または変更する権利を留保します。変更は公開された時点で効力を生じます。変更後も本アプリの使用を継続することにより、変更に同意したものとみなされます。"},jurisdiction:{title:"準拠法と裁判管轄",content:"本規約はスペイン法に準拠し、同法に従って解釈されます。本規約に関連して生じる紛争は、スペインの裁判所の専属管轄権に服するものとします。"},contact:{title:"お問い合わせ",content:"本利用規約に関するご質問や懸念がある場合は、以下までご連絡ください。"}},footer_copy:"GameBob Studio © 2026"}},s={privacy:{discord:{title:"커뮤니티에 가입하세요",subtitle:"공식 서버"},badge:"투명성 보장",title_p1:"개인정보",title_p2:"처리방침",description:"사용자의 안심이 우리의 우선순위입니다. 우리가 게임의 모든 픽셀을 열정으로 만드는 것처럼, 사용자의 데이터를 어떻게 소중히 관리하는지 설명해 드립니다.",last_update:"24/12/2025",sections:{intro:{title:"소개",content:"GameBob은 사용자의 개인정보를 매우 중요하게 생각합니다. 이 방침은 모든 애플리케이션 및 게임에서의 데이터 처리 방식을 설명합니다. 우리는 즐거움이 개인정보에 의존하지 않는 윤리적인 개발을 지향합니다."},collection:{title:"데이터 수집",content:"우리의 게임은 개인 식별 정보를 수집하지 않고 즐길 수 있도록 설계되었습니다. 이름, 이메일 주소 또는 민감한 정보를 요청하지 않습니다. 사용자의 게임 진행 데이터는 전적으로 사용자의 것이며, 우리는 이를 존중합니다."},security:{title:"보안 철학",content:"우리는 'Zero Data' 정책을 시행합니다. 애플리케이션의 로컬 기술 운영에 엄격히 필요하지 않은 정보는 외부 서버에 저장하지 않아 노출 위험을 최소화합니다."},third_party:{title:"제3자 서비스",admob_title:"Google AdMob:",admob_content:"무료 개발 자금을 지원하는 광고 표시에 사용됩니다. Google은 광고 경험을 맞춤화하기 위해 익명의 광고 식별자를 사용할 수 있습니다.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"앱의 안정성 문제를 파악하고 우선순위를 정해 해결하는 데 도움을 주는 오류 모니터링 도구입니다. 오류 발생 시 앱 상태와 충돌에 대한 익명 데이터를 수집합니다."},children:{title:"아동 보호",content:"우리는 국제 아동 보호 규정(COPPA/GDPR)을 엄격히 준수합니다. 우리의 게임은 어떤 상황에서도 13세 미만 아동의 개인정보를 수집하지 않는 안전한 환경입니다."},contact:{title:"변경 및 문의",content:"우리의 방침은 기술의 발전에 따라 변경될 수 있습니다. 게임 경험 보호에 대해 궁금한 점이 있으시면 공식 채널을 통해 언제든지 문의해 주세요."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"법적 프레임워크",title_p1:"이용",title_p2:"약관",description:"게임의 규칙. 더 나은 경험을 위한 투명성과 명확성.",last_update:"02/01/2026",intro_p1:"Game Bob (jjlmoya)이 제공하는 서비스에 오신 것을 환영합니다.",intro_p2:"모바일 애플리케이션('애플리케이션')을 다운로드, 설치 또는 사용하거나 웹사이트에 접속함으로써 귀하는 다음 이용 약관을 준수하는 데 동의하게 됩니다. 이 약관에 동의하지 않으시면 애플리케이션을 사용하지 마시기 바랍니다.",sections:{license:{title:"사용권",content:"사용자에게는 호환되는 모바일 장치에서 개인적이고 비상업적인 목적으로만 애플리케이션을 사용할 수 있는 개인적이고, 비독점적이며, 양도 불가능하고, 취소 가능한 라이선스가 부여됩니다."},acceptable:{title:"허용되는 사용",content:"귀하는 적법한 목적을 위해서만 그리고 이 약관에 따라 애플리케이션을 사용하는 데 동의합니다. 다음 행위는 금지됩니다:",items:["애플리케이션의 소스 코드를 역설계, 역컴파일 또는 추출하려고 시도하는 행위.","우리의 서버나 네트워크를 손상시키거나, 비활성화하거나, 과부하시킬 수 있는 방식으로 애플리케이션을 사용하는 행위.","애플리케이션의 보안 조치나 기술적 제한을 우회하는 행위."]},intellectual:{title:"지적 재산권",content:"애플리케이션의 디자인, 소스 코드, 그래픽, 로고 및 콘텐츠에 대한 모든 지적 재산권은 jjlmoya의 독점적 자산이거나 라이선스 하에 사용됩니다. 사용자에게는 어떠한 소유권도 이전되지 않습니다."},privacy:{discord:{title:"커뮤니티에 가입하세요",subtitle:"공식 서버"},title:"개인정보 보호 및 데이터 보호",content:"귀하의 개인정보는 우리에게 중요합니다. 애플리케이션 사용은 정보 수집, 사용 및 공유 방식(예: 광고 식별자 또는 익명 사용 데이터)을 설명하는 개인정보 처리방침의 적용을 받습니다.",link_text:"개인정보 처리방침 전문 읽기"},third_party:{title:"제3자 서비스",content:"애플리케이션은 제3자 서비스(광고용 Google AdMob 또는 분석용 Firebase 등)를 통합할 수 있습니다. 이러한 서비스의 사용은 해당 제공업체의 약관 및 정책의 적용을 받습니다. Game Bob은 이러한 외부 서비스의 콘텐츠나 관행을 통제하지 않으며 이에 대해 책임을 지지 않습니다."},liability:{title:"책임 제한",content:"애플리케이션은 '있는 그대로' 제공됩니다. Game Bob은 애플리케이션에 오류가 없거나 중단 없이 작동할 것임을 보증하지 않습니다. 법이 허용하는 최대 범위 내에서, 애플리케이션 사용 또는 사용 불능으로 인해 발생하는 직접적, 간접적 또는 결과적 손해에 대해 책임을 지지 않습니다."},modifications:{title:"수정",content:"우리는 언제든지 이 약관을 업데이트하거나 수정할 권리를 보유합니다. 수정 사항은 게시되는 즉시 효력이 발생합니다. 애플리케이션을 계속 사용하면 이러한 수정 사항을 수락하는 것으로 간주됩니다."},jurisdiction:{title:"준거법 및 관할권",content:"이 약관은 스페인 법률에 따라 규율되고 해석됩니다. 이 약관과 관련하여 발생하는 모든 분쟁은 스페인 법원의 전담 관할권에 속합니다."},contact:{title:"문의",content:"이 이용 약관에 대해 질문이나 우려 사항이 있는 경우 다음 주소로 문의해 주세요:"}},footer_copy:"GameBob Studio © 2026"}},l={privacy:{discord:{title:"加入社区",subtitle:"官方服务器"},badge:"完全透明",title_p1:"隐私",title_p2:"政策",description:"您的安心是我们的首要任务。在这里，我们解释了我们如何以创造游戏每个像素的同样热情来照顾您的数据。",last_update:"24/12/2025",sections:{intro:{title:"简介",content:"在 GameBob，我们非常重视用户的隐私。本政策描述了我们所有应用程序和游戏中数据的处理方式。我们相信伦理开发，乐趣不应依赖于您的个人信息。"},collection:{title:"数据收集",content:"我们的游戏旨在让您在不收集个人身份信息的情况下享受乐趣。我们不要求提供姓名、电子邮件或敏感信息。您的进步属于您，我们希望保持这种状态。"},security:{title:"安全理念",content:"我们实施“零数据”政策。我们不在外部服务器上存储任何非应用程序本地技术运行所必需的信息，从而将任何泄露风险降至最低。"},third_party:{title:"第三方服务",admob_title:"Google AdMob:",admob_content:"用于展示资助我们免费开发的广告。Google 可能会使用匿名广告标识符来个性化您的广告体验。",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"帮助我们识别、优先处理和解决应用程序稳定性问题的错误监控工具。它在发生错误时收集有关崩溃和应用程序状态的匿名数据。"},children:{title:"儿童保护",content:"我们严格遵守国际儿童保护法规（COPPA/GDPR）。我们的游戏是安全的环境，在任何情况下都不会收集 13 岁以下儿童的个人信息。"},contact:{title:"更改与联系",content:"我们的政策可能会随着我们技术的发展而演变。如果您对我们如何保护您的游戏体验有任何疑问，可以通过我们的官方渠道联系我们。"}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"法律框架",title_p1:"条款与",title_p2:"条件",description:"游戏规则。透明和清晰，为您提供更好的体验。",last_update:"02/01/2026",intro_p1:"欢迎使用由 Game Bob (jjlmoya) 提供的服务。",intro_p2:"通过下载、安装或使用我们的任何移动应用程序（“应用程序”）或访问我们的网站，即表示您同意受以下条款和条件的约束。如果您不同意这些条款，请勿使用本应用程序。",sections:{license:{title:"使用许可",content:"授予用户个人、非排他性、不可转让且可撤销的许可，以便在兼容的移动设备上使用本应用程序，仅用于个人且非商业目的。"},acceptable:{title:"可接受的使用",content:"您同意仅出于合法目的并按照本条款使用应用程序。禁止：",items:["对应用程序进行逆向工程、反编译或尝试提取源代码。","以可能损坏、禁用或使我们的服务器或网络过载的方式使用应用程序。","绕过应用程序的任何安全措施或技术限制。"]},intellectual:{title:"知识产权",content:"我们应用程序的设计、源代码、图形、徽标和内容的所有知识产权均为 jjlmoya 的专有财产或经许可使用。不向用户转让任何所有权。"},privacy:{discord:{title:"加入社区",subtitle:"官方服务器"},title:"隐私与数据保护",content:"您的隐私对我们非常重要。应用程序的使用还受我们的隐私政策约束，该政策描述了我们如何收集、使用和共享信息（例如广告标识符或匿名使用数据）。",link_text:"阅读完整的隐私政策"},third_party:{title:"第三方服务",content:"应用程序可能会集成第三方服务（例如用于广告的 Google AdMob 或用于分析的 Firebase）。这些服务的使用受这些提供商的条款和政策约束。Game Bob 不控制这些外部服务的内容或做法，也不承担任何责任。"},liability:{title:"责任限制",content:"应用程序按“原样”提供。Game Bob 不保证应用程序没有错误或无间断运行。在法律允许的最大范围内，我们对因使用或无法使用应用程序而产生的任何直接、间接或后果性损害不承担责任。"},modifications:{title:"修改",content:"我们保留随时更新或修改这些条款的权利。修改自发布之日起生效。继续使用应用程序即表示您接受此类修改。"},jurisdiction:{title:"立法与司法管辖",content:"这些条款受西班牙法律管辖并按其解释。与这些条款有关的任何争议均受西班牙法院的排他性管辖。"},contact:{title:"联系我们",content:"如果您对本条款与条件有任何疑问或疑虑，可以通过以下方式联系我们："}},footer_copy:"GameBob Studio © 2026"}},c={privacy:{discord:{title:"Присоединяйтесь к сообществу",subtitle:"Официальный сервер"},badge:"Полная прозрачность",title_p1:"Политика",title_p2:"конфиденциальности",description:"Ваше спокойствие — наш приоритет. Здесь мы объясняем, как мы заботимся о ваших данных с той же страстью, с которой создаем каждый пиксель наших игр.",last_update:"24/12/2025",sections:{intro:{title:"Введение",content:"В GameBob мы очень серьезно относимся к конфиденциальности наших пользователей. Эта политика описывает, как обрабатываются данные во всех наших приложениях и играх. Мы верим в этичную разработку, где удовольствие не зависит от вашей личной информации."},collection:{title:"Сбор данных",content:"Наши игры разработаны так, чтобы ими можно было наслаждаться без сбора личной информации. Мы не запрашиваем имена, адреса электронной почты или конфиденциальную информацию. Ваш прогресс принадлежит вам, и мы хотим, чтобы так оно и оставалось."},security:{title:"Философия безопасности",content:"Мы реализуем политику «Zero Data». Мы не храним информацию на внешних серверах, которая не является строго необходимой для локальной технической работы приложения, сводя к минимуму любой риск утечки."},third_party:{title:"Сторонние сервисы",admob_title:"Google AdMob:",admob_content:"Используется для показа рекламы, которая финансирует нашу бесплатную разработку. Google может использовать анонимные рекламные идентификаторы для персонализации вашей рекламы.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Инструмент мониторинга ошибок, который помогает нам выявлять, приоритизировать и устранять проблемы со стабильностью приложения. Он собирает анонимные данные о сбоях и состоянии приложения в момент ошибки."},children:{title:"Защита детей",content:"Мы строго соблюдаем международные правила защиты детей (COPPA/GDPR). Наши игры — это безопасная среда, где личная информация детей младше 13 лет не собирается ни при каких обстоятельствах."},contact:{title:"Изменения и контакты",content:"Наша политика может меняться вместе с нашими технологиями. Если у вас есть вопросы о том, как мы защищаем ваш игровой опыт, мы на расстоянии одного сообщения через наши официальные каналы."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Правовая база",title_p1:"Условия и",title_p2:"положения",description:"Правила игры. Прозрачность и ясность для лучшего опыта.",last_update:"02/01/2026",intro_p1:"Добро пожаловать в сервисы, предоставляемые Game Bob (Хуан Хосе Лопес Мойя).",intro_p2:"Загружая, устанавливая или используя любое из наших мобильных приложений («Приложение») или заходя на наш веб-сайт, вы соглашаетесь соблюдать следующие Условия и положения. Если вы не согласны с этими условиями, пожалуйста, не используйте Приложение.",sections:{license:{title:"Лицензия на использование",content:"Пользователю предоставляется личная, неисключительная, непередаваемая и отзывная лицензия на использование Приложения на совместимых мобильных устройствах исключительно в личных и некоммерческих целях."},acceptable:{title:"Приемлемое использование",content:"Вы соглашаетесь использовать Приложение только в законных целях и в соответствии с настоящими Условиями. Запрещено:",items:["Выполнять обратную разработку, декомпилировать или пытаться извлечь исходный код Приложения.","Использовать Приложение таким образом, который может повредить, отключить или перегрузить наши серверы или сети.","Обходить любые меры безопасности или технические ограничения Приложения."]},intellectual:{title:"Интеллектуальная собственность",content:"Все права интеллектуальной собственности на дизайн, исходный код, графику, логотипы и содержимое наших приложений являются исключительной собственностью Хуана Хосе Лопеса Мойи или используются по лицензии. Никакие права собственности не передаются пользователю."},privacy:{discord:{title:"Присоединяйтесь к сообществу",subtitle:"Официальный сервер"},title:"Конфиденциальность и защита данных",content:"Ваша конфиденциальность важна для нас. Использование Приложения также регулируется нашей Политикой конфиденциальности, которая описывает, как мы собираем, используем и делимся информацией (например, рекламными идентификаторами или анонимными данными об использовании).",link_text:"Читать полную Политику конфиденциальности"},third_party:{title:"Сторонние сервисы",content:"Приложение может интегрировать сторонние сервисы (такие как Google AdMob для рекламы или Firebase для аналитики). Использование этих сервисов регулируется условиями и политиками этих поставщиков. Game Bob не контролирует и не несет ответственности за контент или методы работы этих внешних сервисов."},liability:{title:"Ограничение ответственности",content:"Приложение предоставляется «как есть». Game Bob не гарантирует, что Приложение будет работать без ошибок или перебоев. В максимальной степени, разрешенной законом, мы не несем ответственности за любой прямой, косвенный или побочный ущерб, возникший в результате использования или невозможности использования Приложения."},modifications:{title:"Изменения",content:"Мы оставляем за собой право обновлять или изменять настоящие Условия в любое время. Изменения вступают в силу с момента их публикации. Дальнейшее использование Приложения означает ваше согласие с такими изменениями."},jurisdiction:{title:"Законодательство и юрисдикция",content:"Настоящие Условия регулируются и интерпретируются в соответствии с законодательством Испании. Любые споры, возникающие в связи с настоящими Условиями, подлежат исключительной юрисдикции испанских судов."},contact:{title:"Контакты",content:"Если у вас есть вопросы или опасения по поводу настоящих Условий и положений, вы можете связаться с нами по адресу:"}},footer_copy:"GameBob Studio © 2026"}},d={privacy:{discord:{title:"Topluluğa katılın",subtitle:"Resmi Sunucu"},badge:"Tam Şeffaflık",title_p1:"Gizlilik",title_p2:"Politikası",description:"Huzurunuz bizim önceliğimizdir. Burada, oyunlarımızın her bir pikselini oluştururken gösterdiğimiz tutkuyla verilerinize nasıl sahip çıktığımızı açıklıyoruz.",last_update:"24/12/2025",sections:{intro:{title:"Giriş",content:"GameBob'da kullanıcılarımızın gizliliğini çok ciddiye alıyoruz. Bu politika, tüm uygulamalarımızda ve oyunlarımızda verilerin nasıl işlendiğini açıklar. Eğlencenin kişisel bilgilerinize bağlı olmadığı etik bir geliştirmeye inanıyoruz."},collection:{title:"Veri Toplama",content:"Oyunlarımız, kişisel olarak tanımlanabilir bilgiler toplanmadan keyif alınacak şekilde tasarlanmıştır. İsim, e-posta veya hassas bilgiler talep etmiyoruz. İlerlemeniz size aittir ve öyle kalmasını istiyoruz."},security:{title:"Güvenlik Felsefesi",content:"Bir 'Sıfır Veri' politikası uyguluyoruz. Uygulamanın yerel teknik çalışması için kesinlikle gerekli olmayan bilgileri harici sunucularda saklamıyoruz, böylece her türlü maruz kalma riskini en aza indiriyoruz."},third_party:{title:"Üçüncü Taraf Servisler",admob_title:"Google AdMob:",admob_content:"Ücretsiz geliştirmemizi finanse eden reklamları göstermek için kullanılır. Google, reklam deneyiminizi kişiselleştirmek için anonim reklam tanımlayıcıları kullanabilir.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Uygulama kararlılığı sorunlarını belirlememize, önceliklendirmemize ve düzeltmemize yardımcı olan hata izleme aracı. Hata anında kilitlenmeler ve uygulama durumu hakkında anonim veriler toplar."},children:{title:"Çocukların Korunması",content:"Uluslararası çocuk koruma düzenlemelerine (COPPA/GDPR) kesinlikle uyuyoruz. Oyunlarımız, hiçbir koşulda 13 yaşın altındaki çocuklardan kişisel bilgilerin toplanmadığı güvenli ortamlardır."},contact:{title:"Değişiklikler ve İletişim",content:"Politikamız teknolojimizle birlikte gelişebilir. Oyun deneyiminizi nasıl koruduğumuz hakkında herhangi bir sorunuz varsa, resmi kanallarımız aracılığıyla bir mesaj uzağınızdayız."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Yasal Çerçeve",title_p1:"Şartlar ve",title_p2:"Koşullar",description:"Oyunun kuralları. Daha iyi bir deneyim için şeffaflık ve netlik.",last_update:"02/01/2026",intro_p1:"Game Bob (jjlmoya) tarafından sağlanan hizmetlere hoş geldiniz.",intro_p2:'Mobil uygulamalarımızdan herhangi birini ("Uygulama") indirerek, kurarak veya kullanarak ya da web sitemize erişerek, aşağıdaki Şartlar ve Koşullara bağlı kalmayı kabul etmiş olursunuz. Bu şartları kabul etmiyorsanız, lütfen Uygulamayı kullanmayın.',sections:{license:{title:"Kullanım Lisansı",content:"Kullanıcıya Uygulamayı uyumlu mobil cihazlarda, yalnızca kişisel ve ticari olmayan amaçlarla kullanması için kişisel, münhasır olmayan, devredilemez ve iptal edilebilir bir lisans verilir."},acceptable:{title:"Kabul Edilebilir Kullanım",content:"Uygulamayı yalnızca yasal amaçlarla ve bu Şartlara uygun olarak kullanmayı kabul edersiniz. Şunlar yasaktır:",items:["Uygulamanın kaynak kodunu tersine mühendislik yapmak, derlemesini çözmek veya çıkarmaya çalışmak.","Uygulamayı sunucularımıza veya ağlarımıza zarar verebilecek, devre dışı bırakabilecek veya aşırı yükleyebilecek şekilde kullanmak.","Uygulamanın herhangi bir güvenlik önlemini veya teknik kısıtlamasını atlatmak."]},intellectual:{title:"Fikri Mülkiyet",content:"Uygulamalarımızın tasarımı, kaynak kodu, grafikleri, logoları ve içeriği üzerindeki tüm fikri mülkiyet hakları jjlmoya'nın münhasır mülkiyetindedir veya lisans altında kullanılmaktadır. Kullanıcıya herhangi bir mülkiyet hakkı devredilmez."},privacy:{discord:{title:"Topluluğa katılın",subtitle:"Resmi Sunucu"},title:"Gizlilik ve Veri Koruma",content:"Gizliliğiniz bizim için önemlidir. Uygulamanın kullanımı ayrıca, bilgileri nasıl topladığımızı, kullandığımızı ve paylaştığımızı (örneğin, reklam tanımlayıcıları veya anonim kullanım verileri) açıklayan Gizlilik Politikamıza tabidir.",link_text:"Gizlilik Politikasının tamamını oku"},third_party:{title:"Üçüncü Taraf Servisler",content:"Uygulama üçüncü taraf servisleri (reklam için Google AdMob veya analiz için Firebase gibi) entegre edebilir. Bu servislerin kullanımı, söz konusu sağlayıcıların şartlarına ve politikalarına tabidir. Game Bob, bu harici servislerin içeriğini veya uygulamalarını kontrol etmez ve sorumluluk kabul etmez."},liability:{title:"Sorumluluğun Sınırlandırılması",content:'Uygulama "olduğu gibi" sunulmaktadır. Game Bob, Uygulamanın hatasız olacağını veya kesintisiz çalışacağını garanti etmez. Yasaların izin verdiği azami ölçüde, Uygulamanın kullanımından veya kullanılamamasından kaynaklanan doğrudan, dolaylı veya sonuçsal zararlardan sorumlu olmayacağız.'},modifications:{title:"Değişiklikler",content:"Bu Şartları herhangi bir zamanda güncelleme veya değiştirme hakkımızı saklı tutarız. Değişiklikler yayınlandığı anda yürürlüğe girer. Uygulamayı kullanmaya devam etmeniz, söz konusu değişiklikleri kabul ettiğiniz anlamına gelir."},jurisdiction:{title:"Mevzuat ve Yetki",content:"Bu Şartlar İspanya yasalarına göre yönetilecek ve yorumlanacaktır. Bu Şartlarla bağlantılı olarak ortaya çıkan her türlü ihtilaf, İspanyol mahkemelerinin münhasır yetkisine tabi olacaktır."},contact:{title:"İletişim",content:"Bu Şartlar ve Koşullar hakkında herhangi bir sorunuz veya endişeniz varsa, bizimle şu adresten iletişime geçebilirsiniz:"}},footer_copy:"GameBob Studio © 2026"}},u={privacy:{discord:{title:"Word lid van de community",subtitle:"Officiële server"},badge:"Volledige Transparantie",title_p1:"Privacy",title_p2:"beleid",description:"Uw gemoedsrust is onze prioriteit. Hier leggen we uit hoe we voor uw gegevens zorgen met dezelfde passie waarmee we elke pixel van onze games creëren.",last_update:"24/12/2025",sections:{intro:{title:"Inleiding",content:"Bij GameBob nemen we de privacy van onze gebruikers zeer serieus. Dit beleid beschrijft hoe gegevens worden behandeld in al onze applicaties en games. Wij geloven in ethische ontwikkeling waarbij plezier niet afhankelijk is van uw persoonlijke informatie."},collection:{title:"Gegevensverzameling",content:"Onze games zijn ontworpen om van te genieten zonder persoonlijk identificeerbare informatie te verzamelen. We vragen niet om namen, e-mailadressen of gevoelige informatie. Uw voortgang is van u, and dat willen we zo houden."},security:{title:"Veiligheidsfilosofie",content:"Wij hanteren een 'Zero Data'-beleid. We slaan geen informatie op externe servers op die niet strikt noodzakelijk is voor de lokale technische werking van de applicatie, waardoor elk risico op blootstelling wordt geminimaliseerd."},third_party:{title:"Diensten van derden",admob_title:"Google AdMob:",admob_content:"Gebruikt om advertenties te tonen die onze gratis ontwikkeling financieren. Google kan anonieme advertentie-ID's gebruiken om uw advertentie-ervaring te personaliseren.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Foutopsporingstool die ons helpt bij het identificeren, prioriteren en oplossen van stabiliteitsproblemen in de app. Het verzamelt anonieme gegevens over crashes en de status van de app op het moment van de fout."},children:{title:"Kinderbescherming",content:"Wij houden ons strikt aan de internationale regels voor kinderbescherming (COPPA/AVG). Onze games zijn veilige omgevingen waar onder geen beding persoonlijke informatie van kinderen onder de 13 jaar wordt verzameld."},contact:{title:"Wijzigingen en contact",content:"Ons beleid kan evolueren samen met onze technologie. Als u vragen heeft over hoe we uw game-ervaring beschermen, zijn we slechts een bericht verwijderd via onze officiële kanalen."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Juridisch Kader",title_p1:"Algemene",title_p2:"Voorwaarden",description:"De regels van het spel. Transparantie en duidelijkheid voor een betere ervaring.",last_update:"02/01/2026",intro_p1:"Welkom bij de diensten van Game Bob (jjlmoya).",intro_p2:'Door een van onze mobiele applicaties ("de Applicatie") te downloaden, installeren of gebruiken, of door onze website te bezoeken, gaat u akkoord met de volgende Algemene Voorwaarden. Indien u niet akkoord gaat met deze voorwaarden, gebruik de Applicatie dan niet.',sections:{license:{title:"Gebruikslicentie",content:"De gebruiker krijgt een persoonlijke, niet-exclusieve, niet-overdraagbare en herroepbare licentie om de Applicatie te gebruiken op compatibele mobiele apparaten, uitsluitend voor persoonlijke en niet-commerciële doeleinden."},acceptable:{title:"Acceptabel gebruik",content:"U stemt ermee in de Applicatie alleen te gebruiken voor wettige doeleinden en in overeenstemming met deze Voorwaarden. Het is verboden om:",items:["De broncode van de Applicatie te reverse engineeren, decompileren of proberen te extraheren.","De Applicatie te gebruiken op een manier die onze servers of netwerken zou kunnen beschadigen, uitschakelen of overbelasten.","Beveiligingsmaatregelen of technische beperkingen van de Applicatie te omzeilen."]},intellectual:{title:"Intellectueel Eigendom",content:"Alle intellectuele eigendomsrechten op het ontwerp, de broncode, graphics, logo's en inhoud van onze applicaties zijn het exclusieve eigendom van jjlmoya of worden onder licentie gebruikt. Er worden geen eigendomsrechten overgedragen aan de gebruiker."},privacy:{discord:{title:"Word lid van de community",subtitle:"Officiële server"},title:"Privacy en Gegevensbescherming",content:"Uw privacy is belangrijk voor ons. Het gebruik van de Applicatie wordt ook beheerst door ons Privacybeleid, dat beschrijft hoe we informatie verzamelen, gebruiken en delen (bijv. advertentie-ID's of anonieme gebruiksgegevens).",link_text:"Lees het volledige Privacybeleid"},third_party:{title:"Diensten van derden",content:"De applicatie kan diensten van derden integreren (zoals Google AdMob voor advertenties of Firebase voor analytics). Het gebruik van deze diensten is onderworpen aan de voorwaarden en het beleid van die aanbieders. Game Bob heeft geen controle over en is niet verantwoordelijk voor de inhoud of praktijken van deze externe diensten."},liability:{title:"Beperking van Aansprakelijkheid",content:'De Applicatie wordt geleverd "zoals deze is". Game Bob garandeert niet dat de Applicatie foutloos zal zijn of zonder onderbrekingen zal werken. Voor zover wettelijk toegestaan, zijn wij niet aansprakelijk voor enige directe, indirecte of gevolgschade die voortvloeit uit het gebruik of het onvermogen om de Applicatie te gebruiken.'},modifications:{title:"Wijzigingen",content:"Wij behouden ons het recht voor om deze Voorwaarden op elk moment bij te werken of te wijzigen. Wijzigingen worden van kracht op het moment van publicatie. Voortgezet gebruik van de Applicatie houdt uw acceptatie van dergelijke wijzigingen in."},jurisdiction:{title:"Wetgeving en Jurisdictie",content:"Deze Voorwaarden worden beheerst door en geïnterpreteerd in overeenstemming met de wetten van Spanje. Eventuele geschillen die voortvloeien uit deze Voorwaarden zijn onderworpen aan de exclusieve jurisdictie van de Spaanse rechtbanken."},contact:{title:"Contact",content:"Indien u vragen of opmerkingen heeft over deze Algemene Voorwaarden, kunt u contact met ons opnemen via:"}},footer_copy:"GameBob Studio © 2026"}},p={privacy:{discord:{title:"Dołącz do społeczności",subtitle:"Oficjalny serwer"},badge:"Pełna przejrzystość",title_p1:"Polityka",title_p2:"prywatności",description:"Twój spokój jest naszym priorytetem. Tutaj wyjaśniamy, jak dbamy o Twoje dane z taką samą pasją, z jaką tworzymy każdy piksel naszych gier.",last_update:"24/12/2025",sections:{intro:{title:"Wstęp",content:"W GameBob traktujemy prywatność naszych użytkowników bardzo poważnie. Niniejsza polityka opisuje sposób przetwarzania danych we wszystkich naszych aplikacjach i grach. Wierzymy w etyczny rozwój, w którym zabawa nie zależy od Twoich danych osobowych."},collection:{title:"Gromadzenie danych",content:"Nasze gry są zaprojektowane tak, aby można było się nimi cieszyć bez gromadzenia danych umożliwiających identyfikację osoby. Nie prosimy o imiona, adresy e-mail ani wrażliwe informacje. Twój postęp należy do Ciebie i chcemy, aby tak pozostało."},security:{title:"Filozofia bezpieczeństwa",content:"Stosujemy politykę „Zero Data”. Nie przechowujemy na zewnętrznych serwerach żadnych informacji, które nie są ściśle niezbędne do lokalnego technicznego działania aplikacji, minimalizując ryzyko wycieku."},third_party:{title:"Usługi osób trzecich",admob_title:"Google AdMob:",admob_content:"Używane do wyświetlania reklam finansujących nasz bezpłatny rozwój. Google może używać anonimowych identyfikatorów reklamowych w celu personalizacji reklam.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Narzędzie do monitorowania błędów, które pomaga nam identyfikować, priorytetyzować i naprawiać problemy ze stabilnością aplikacji. Gromadzi anonimowe dane o awariach i stanie aplikacji w momencie wystąpienia błędu."},children:{title:"Ochrona dzieci",content:"Ściśle przestrzegamy międzynarodowych przepisów dotyczących ochrony dzieci (COPPA/RODO). Nasze gry to bezpieczne środowiska, w których w żadnym wypadku nie są gromadzone dane osobowe dzieci poniżej 13 roku życia."},contact:{title:"Zmiany i kontakt",content:"Nasza polityka może ewoluować wraz z naszą technologią. Jeśli masz jakiekolwiek pytania dotyczące tego, jak chronimy Twoje wrażenia z gry, jesteśmy dostępni za pośrednictwem naszych oficjalnych kanałów."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Ramy prawne",title_p1:"Regulamin i",title_p2:"warunki",description:"Zasady gry. Przejrzystość i klarowność dla lepszych wrażeń.",last_update:"02/01/2026",intro_p1:"Witamy w usługach świadczonych przez Game Bob (jjlmoya).",intro_p2:"Pobierając, instalując lub korzystając z którejkolwiek z naszych aplikacji mobilnych („Aplikacja”) lub uzyskując dostęp do naszej witryny internetowej, wyrażasz zgodę na przestrzeganie poniższych Warunków i postanowień. Jeśli nie zgadzasz się z tymi warunkami, prosimy o niekorzystanie z Aplikacji.",sections:{license:{title:"Licencja na użytkowanie",content:"Użytkownikowi udziela się osobistej, niewyłącznej, niezbywalnej i odwołalnej licencji na korzystanie z Aplikacji na kompatybilnych urządzeniach mobilnych, wyłącznie do celów osobistych i niekomercyjnych."},acceptable:{title:"Dopuszczalne użytkowanie",content:"Zgadzasz się korzystać z Aplikacji wyłącznie w celach zgodnych z prawem i niniejszymi Warunkami. Zabrania się:",items:["Inżynierii wstecznej, dekompilacji lub prób wydobycia kodu źródłowego Aplikacji.","Korzystania z Aplikacji w sposób, który mógłby uszkodzić, wyłączyć lub przeciążyć nasze serwery lub sieci.","Omijania jakichkolwiek środków bezpieczeństwa lub ograniczeń technicznych Aplikacji."]},intellectual:{title:"Własność intelektualna",content:"Wszelkie prawa własności intelektualnej do projektu, kodu źródłowego, grafiki, logo i treści naszych aplikacji są wyłączną własnością Juana José Lópeza Moyi lub są używane na podstawie licencji. Żadne prawa własności nie są przenoszone na użytkownika."},privacy:{discord:{title:"Dołącz do społeczności",subtitle:"Oficjalny serwer"},title:"Prywatność i ochrona danych",content:"Twoja prywatność jest dla nas ważna. Korzystanie z Aplikacji podlega również naszej Polityce prywatności, która opisuje, w jaki sposób gromadzimy, używamy i udostępniamy informacje (np. identyfikatory reklamowe lub anonimowe dane o użytkowaniu).",link_text:"Przeczytaj pełną Politykę prywatności"},third_party:{title:"Usługi osób trzecich",content:"Aplikacja może integrować usługi osób trzecich (takie jak Google AdMob dla reklam lub Firebase dla analityki). Korzystanie z tych usług podlega warunkom i politykom tych dostawców. Game Bob nie kontroluje ani nie ponosi odpowiedzialności za treści ani praktyki tych zewnętrznych usług."},liability:{title:"Ograniczenie odpowiedzialności",content:"Aplikacja jest dostarczana w stanie, w jakim się znajduje („as is”). Game Bob nie gwarantuje, że Aplikacja będzie wolna od błędów lub będzie działać bez przerw. W maksymalnym zakresie dozwolonym przez prawo nie ponosimy odpowiedzialności za jakiekolwiek bezpośrednie, pośrednie lub wtórne szkody wynikające z korzystania lub niemożności korzystania z Aplikacji."},modifications:{title:"Zmiany",content:"Zastrzegamy sobie prawo do aktualizacji lub zmiany niniejszych Warunków w dowolnym momencie. Zmiany wchodzą w życie z chwilą ich opublikowania. Dalsze korzystanie z Aplikacji oznacza akceptację takich zmian."},jurisdiction:{title:"Ustawodawstwo i jurysdykcja",content:"Niniejsze Warunki podlegają prawu hiszpańskiemu i zgodnie z nim będą interpretowane. Wszelkie spory powstałe w związku z niniejszymi Warunkami podlegają wyłącznej jurysdykcji sądów hiszpańskich."},contact:{title:"Kontakt",content:"Jeśli masz jakiekolwiek pytania lub wątpliwości dotyczące niniejszych Warunków i postanowień, możesz skontaktować się z nami pod adresem:"}},footer_copy:"GameBob Studio © 2026"}},m={privacy:{discord:{title:"Gå med i gemenskapen",subtitle:"Officiell server"},badge:"Full Transparens",title_p1:"Integritets",title_p2:"policy",description:"Din trygghet är vår prioritet. Här förklarar vi hur vi tar hand om din data med samma passion som vi skapar varje pixel i våra spel.",last_update:"24/12/2025",sections:{intro:{title:"Introduktion",content:"På GameBob tar vi våra användares integritet på största allvar. Denna policy beskriver hur data hanteras i alla våra applikationer och spel. Vi tror på etisk utveckling där spelglädje inte beror på din personliga information."},collection:{title:"Datainsamling",content:"Våra spel är designade för att kunna njutas utan att samla in personligt identifierbar information. Vi efterfrågar inte namn, e-postadresser eller känslig information. Dina framsteg är dina egna, and det vill vi att det ska förbli."},security:{title:"Säkerhetsfilosofi",content:"Vi tillämpar en 'Zero Data'-policy. Vi lagrar ingen information på externa servrar som inte är strikt nödvändig för applikationens lokala tekniska drift, vilket minimerar alla risker för exponering."},third_party:{title:"Tredjepartstjänster",admob_title:"Google AdMob:",admob_content:"Används för att visa annonser som finansierar vår kostnadsfria utveckling. Google kan använda anonyma annonsidentifierare för att personifiera din annonsupplevelse.",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"Felövervakningsverktyg som hjälper oss att identifiera, prioritera och åtgärda stabilitetsproblem i appen. Det samlar in anonyma data om krascher och appens tillstånd vid tidpunkten för felet."},children:{title:"Barnskydd",content:"Vi följer strikt internationella regler för barnskydd (COPPA/GDPR). Våra spel är säkra miljöer där personlig information från barn under 13 år inte samlas in under några omständigheter."},contact:{title:"Ändringar och kontakt",content:"Vår policy kan utvecklas tillsammans med vår teknik. Om du har några frågor om hur vi skyddar din spelupplevelse är vi bara ett meddelande bort via våra officiella kanaler."}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"Juridisk Ram",title_p1:"Regler och",title_p2:"Villkor",description:"Spelets regler. Transparens och tydlighet för en bättre upplevelse.",last_update:"02/01/2026",intro_p1:"Välkommen till tjänsterna som tillhandahålls av Game Bob (jjlmoya).",intro_p2:'Genom att ladda ner, installera eller använda någon av våra mobilapplikationer ("Applikationen") eller gå in på vår webbplats, godkänner du att vara bunden av följande Regler och Villkor. Om du inte godkänner dessa villkor, vänligen använd inte Applikationen.',sections:{license:{title:"Användarlicens",content:"Användaren beviljas en personlig, icke-exklusiv, icke-överlåtbar och återkallelig licens att använda Applikationen på kompatibla mobila enheter, uteslutande för personliga och icke-kommersiella ändamål."},acceptable:{title:"Acceptabel användning",content:"Du samtycker till att endast använda Applikationen för lagliga ändamål och i enlighet med dessa Villkor. Det är förbjudet att:",items:["Utföra reverse engineering, dekompilera eller försöka extrahera källkoden för Applikationen.","Använda Applikationen på ett sätt som kan skada, inaktivera eller överbelasta våra servrar eller nätverk.","Kringgå någon säkerhetsåtgärd eller teknisk begränsning i Applikationen."]},intellectual:{title:"Immateriella rättigheter",content:"Alla immateriella rättigheter till design, källkod, grafik, logotyper och innehåll i våra applikationer är jjlmoyas exklusiva egendom eller används under licens. Inga äganderätter överförs till användaren."},privacy:{discord:{title:"Gå med i gemenskapen",subtitle:"Officiell server"},title:"Integritet och dataskydd",content:"Din integritet är viktig för oss. Användningen av Applikationen styrs också av vår integritetspolicy, som beskriver hur vi samlar in, använder och delar information (t.ex. annonsidentifierare eller anonyma användningsdata).",link_text:"Läs hela integritetspolicyn"},third_party:{title:"Tredjepartstjänster",content:"Applikationen kan integrera tredjepartstjänster (som Google AdMob för annonsering eller Firebase för analys). Användningen av dessa tjänster omfattas av villkoren och policyerna för dessa leverantörer. Game Bob kontrollerar inte och tar inget ansvar för innehållet eller praxis i dessa externa tjänster."},liability:{title:"Ansvarsbegränsning",content:'Applikationen tillhandahålls i befintligt skick ("as is"). Game Bob garanterar inte att Applikationen kommer att vara felfri eller fungera utan avbrott. I den utsträckning det är tillåtet enligt lag ansvarar vi inte för några direkta, indirekta eller följdskador som uppstår till följd av användning eller oförmåga att använda Applikationen.'},modifications:{title:"Ändringar",content:"Vi förbehåller oss rätten att när som ordning uppdatera eller ändra dessa Villkor. Ändringar träder i kraft vid tidpunkten för publicering. Fortsatt användning av Applikationen utgör ditt godkännande av sådana ändringar."},jurisdiction:{title:"Lagstiftning och jurisdiktion",content:"Dessa Villkor ska styras av och tolkas i enlighet med Spaniens lagar. Eventuella tvister som uppstår i samband med dessa Villkor ska omfattas av den exklusiva jurisdiktionen för spanska domstolar."},contact:{title:"Kontakt",content:"Om du har några frågor eller funderingar kring dessa Regler och Villkor kan du kontakta oss på:"}},footer_copy:"GameBob Studio © 2026"}},g={privacy:{discord:{title:"समुदाय में शामिल हों",subtitle:"आधिकारिक सर्वर"},badge:"पूर्ण पारदर्शिता",title_p1:"गोपनीयता",title_p2:"नीति",description:"आपकी मानसिक शांति हमारी प्राथमिकता है। यहाँ हम बताते हैं कि हम आपके डेटा की देखभाल उसी जुनून के साथ करते हैं जिसके साथ हम अपने गेम का हर पिक्सेल बनाते हैं।",last_update:"24/12/2025",sections:{intro:{title:"परिचय",content:"GameBob में, हम अपने उपयोगकर्ताओं की गोपनीयता को बहुत गंभीरता से लेते हैं। यह नीति बताती है कि हमारे सभी एप्लिकेशन और गेम में डेटा कैसे संभाला जाता है। हम नैतिक विकास में विश्वास करते हैं जहाँ मज़ा आपकी व्यक्तिगत जानकारी पर निर्भर नहीं करता है।"},collection:{title:"डेटा संग्रह",content:"हमारे गेम व्यक्तिगत पहचान योग्य जानकारी एकत्र किए बिना आनंद लेने के लिए डिज़ाइन किए गए हैं। हम नाम, ईमेल या संवेदनशील जानकारी नहीं मांगते हैं। आपकी प्रगति आपकी है, और हम चाहते हैं कि यह वैसी ही बनी रहे।"},security:{title:"सुरक्षा दर्शन",content:"हम 'Zero Data' नीति लागू करते हैं। हम बाहरी सर्वर पर ऐसी कोई जानकारी संग्रहीत नहीं करते हैं जो एप्लिकेशन के स्थानीय तकनीकी संचालन के लिए सख्ती से आवश्यक नहीं है, जिससे किसी भी जोखिम को कम किया जा सके।"},third_party:{title:"तृतीय-पक्ष सेवाएँ",admob_title:"Google AdMob:",admob_content:"हमारे मुफ्त विकास को वित्तपोषित करने वाले विज्ञापन दिखाने के लिए उपयोग किया जाता है। Google आपके विज्ञापन अनुभव को वैयक्तिकृत करने के लिए अनाम विज्ञापन पहचानकर्ताओं का उपयोग कर सकता है।",crashlytics_title:"Firebase Crashlytics:",crashlytics_content:"त्रुटि निगरानी उपकरण जो हमें ऐप स्थिरता समस्याओं की पहचान करने, प्राथमिकता देने और ठीक करने में मदद करता है। यह त्रुटि के समय क्रैश और ऐप स्थिति के बारे में अनाम डेटा एकत्र करता है।"},children:{title:"बाल सुरक्षा",content:"हम अंतरराष्ट्रीय बाल सुरक्षा नियमों (COPPA/GDPR) का कड़ाई से पालन करते हैं। हमारे गेम सुरक्षित वातावरण हैं जहाँ किसी भी परिस्थिति में 13 वर्ष से कम उम्र के बच्चों की व्यक्तिगत जानकारी एकत्र नहीं की जाती है।"},contact:{title:"परिवर्तन और संपर्क",content:"हमारी नीति हमारी तकनीक के साथ विकसित हो सकती है। यदि आपके पास इस बारे में कोई प्रश्न हैं कि हम आपके गेमिंग अनुभव को कैसे सुरक्षित रखते हैं, तो हम अपने आधिकारिक चैनलों के माध्यम से संदेश की दूरी पर हैं।"}},footer_copy:"GameBob Studio © 2026"},terms:{badge:"कानूनी ढांचा",title_p1:"नियम एवं",title_p2:"शर्तें",description:"खेल के नियम। बेहतर अनुभव के लिए पारदर्शिता और स्पष्टता।",last_update:"02/01/2026",intro_p1:"Game Bob (jjlmoya) द्वारा प्रदान की गई सेवाओं में आपका स्वागत है।",intro_p2:'हमारे किसी भी मोबाइल एप्लिकेशन ("एप्लिकेशन") को डाउनलोड, इंस्टॉल या उपयोग करके या हमारी वेबसाइट पर जाकर, आप निम्नलिखित नियमों और शर्तों से बंधे होने के लिए सहमत होते हैं। यदि आप इन शर्तों से सहमत नहीं हैं, तो कृपया एप्लिकेशन का उपयोग न करें।',sections:{license:{title:"उपयोग का लाइसेंस",content:"उपयोगकर्ता को संगत मोबाइल उपकरणों पर एप्लिकेशन का उपयोग करने के लिए एक व्यक्तिगत, गैर-अनन्य, गैर-हस्तांतरणीय और प्रतिसंहरणीय लाइसेंस दिया जाता है, जो विशेष रूप से व्यक्तिगत और गैर-व्यावसायिक उद्देश्यों के लिए होता है।"},acceptable:{title:"स्वीकार्य उपयोग",content:"आप एप्लिकेशन का उपयोग केवल वैध उद्देश्यों के लिए और इन शर्तों के अनुसार करने के लिए सहमत हैं। निम्नलिखित निषिद्ध है:",items:["एप्लिकेशन के स्रोत कोड को रिवर्स इंजीनियर, डिकम्पाइल या निकालने का प्रयास करना।","एप्लिकेशन का उपयोग इस तरह से करना जिससे हमारे सर्वर या नेटवर्क को नुकसान हो, अक्षम हो या ओवरलोड हो।","एप्लिकेशन के किसी भी सुरक्षा उपाय या तकनीकी प्रतिबंध को दरकिनार करना।"]},intellectual:{title:"बौद्धिक संपदा",content:"हमारे एप्लिकेशन के डिज़ाइन, स्रोत कोड, ग्राफिक्स, लोगो और सामग्री पर सभी बौद्धिक संपदा अधिकार jjlmoya की अनन्य संपत्ति हैं या लाइसेंस के तहत उपयोग किए जाते हैं। उपयोगकर्ता को कोई स्वामित्व अधिकार हस्तांतरित नहीं किया जाता है।"},privacy:{discord:{title:"समुदाय में शामिल हों",subtitle:"आधिकारिक सर्वर"},title:"गोपनीयता और डेटा सुरक्षा",content:"आपकी गोपनीयता हमारे लिए महत्वपूर्ण है। एप्लिकेशन का उपयोग हमारी गोपनीयता नीति द्वारा भी शासित होता है, जो वर्णन करती है कि हम जानकारी (जैसे विज्ञापन पहचानकर्ता या अनाम उपयोग डेटा) कैसे एकत्र करते हैं, उपयोग करते हैं और साझा करते हैं।",link_text:"पूरी गोपनीयता नीति पढ़ें"},third_party:{title:"तृतीय-पक्ष सेवाएँ",content:"एप्लिकेशन तृतीय-पक्ष सेवाओं (जैसे विज्ञापन के लिए Google AdMob या विश्लेषण के लिए Firebase) को एकीकृत कर सकता है। इन सेवाओं का उपयोग उन प्रदाताओं की शर्तों और नीतियों के अधीन है। Game Bob इन बाहरी सेवाओं की सामग्री या प्रथाओं को नियंत्रित नहीं करता है और कोई जिम्मेदारी नहीं लेता है।"},liability:{title:"दायित्व की सीमा",content:'एप्लिकेशन "जैसा है" प्रदान किया जाता है। Game Bob यह गारंटी नहीं देता है कि एप्लिकेशन त्रुटि-मुक्त होगा या बिना किसी रुकावट के काम करेगा। कानून द्वारा अनुमत अधिकतम सीमा तक, हम एप्लिकेशन के उपयोग या उपयोग करने में असमर्थता से उत्पन्न होने वाले किसी भी प्रत्यक्ष, अप्रत्यक्ष या परिणामी नुकसान के लिए उत्तरदायी नहीं होंगे।'},modifications:{title:"संशोधन",content:"हम किसी भी समय इन शर्तों को अपडेट करने या संशोधित करने का अधिकार सुरक्षित रखते हैं। संशोधन प्रकाशन के समय से प्रभावी होंगे। एप्लिकेशन का निरंतर उपयोग आपके द्वारा ऐसे संशोधनों की स्वीकृति माना जाएगा।"},jurisdiction:{title:"कानून और क्षेत्राधिकार",content:"ये शर्तें स्पेन के कानूनों के अधीन होंगी और उनके अनुसार व्याख्या की जाएंगी। इन शर्तों के संबंध में उत्पन्न होने वाला कोई भी विवाद स्पेनिश अदालतों के अनन्य क्षेत्राधिकार के अधीन होगा।"},contact:{title:"संपर्क",content:"यदि आपके पास इन नियमों और शर्तों के बारे में कोई प्रश्न या चिंता है, तो आप हमसे यहाँ संपर्क कर सकते हैं:"}},footer_copy:"GameBob Studio © 2026"}},b={en:e,es:i,de:t,fr:n,it:a,pt:o,ja:r,ko:s,zh:l,ru:c,tr:d,nl:u,pl:p,sv:m,hi:g};export{b as L};
